// Project defines model for Project.
type Project struct {
	// ChromaPath Resolved chromem-go collection directory for this project. NULL when not computed.
	ChromaPath      *string `json:"chroma_path,omitempty"`
	ChromaSizeBytes *int64  `json:"chroma_size_bytes,omitempty"`

	// ContainerPath Path inside the container (often equal to host_path).
	ContainerPath string    `json:"container_path"`
	CreatedAt     time.Time `json:"created_at"`

	// DisplayPath Human-readable path. The real filesystem path for local projects,
	// the github path for external ones. host_path is the identity key
	// (namespaced per machine for locals) — clients should show this.
	DisplayPath *string `json:"display_path,omitempty"`

	// FullSyncReason Human-readable explanation shown with the out-of-sync badge.
	// NULL when full_sync_required is false.
	FullSyncReason *string `json:"full_sync_reason,omitempty"`

	// FullSyncRequired True when this project's index is format-stale (e.g. the
	// chunker/embedding format changed under it) and needs a complete
	// rebuild. Informational only — it drives the dashboard "out of sync"
	// badge; the admin triggers the resync, which clears the flag on the
	// next successful full run. Absent/false means in sync.
	FullSyncRequired *bool `json:"full_sync_required,omitempty"`

	// HostPath Absolute filesystem path on the operator's machine.
	HostPath string `json:"host_path"`

	// IndexedWithModel Embedding model identifier active when this project was last
	// (re)indexed. NULL on rows that pre-date drift tracking — the
	// dashboard treats NULL as "Unknown" rather than as drift.
	IndexedWithModel *string    `json:"indexed_with_model,omitempty"`
	Languages        []string   `json:"languages"`
	LastIndexedAt    *time.Time `json:"last_indexed_at"`

	// MachineId Per-machine UUID a local project was indexed on. NULL for external/legacy.
	MachineId *string `json:"machine_id,omitempty"`

	// MachineLabel os.Hostname() of the indexing machine — display only.
	MachineLabel *string `json:"machine_label,omitempty"`

	// OwnerUserId User who owns this personal (locally indexed) project. NULL means
	// ownerless — the canonical state for EXTERNAL projects (those with a
	// git_repos peer), which are admin-administered and reachable only via
	// a view-group share.
	OwnerUserId *string `json:"owner_user_id"`

	// PathHash First 16 hex chars of SHA1(host_path) — stable URL identifier.
	PathHash string          `json:"path_hash"`
	Settings ProjectSettings `json:"settings"`

	// SqlitePath Resolved SQLite database path for the active model. NULL on dashboards that don't expose storage info.
	SqlitePath      *string       `json:"sqlite_path,omitempty"`
	SqliteSizeBytes *int64        `json:"sqlite_size_bytes,omitempty"`
	Stats           ProjectStats  `json:"stats"`
	Status          ProjectStatus `json:"status"`
	UpdatedAt       time.Time     `json:"updated_at"`
}

